namespace ReqArbiter.Core.Projects;

// A file uploaded to a project. The content lives on disk; this record keeps
// its metadata.
public class ProjectFile
{
    public int Id { get; set; }

    public int ProjectId { get; set; }

    // Name as uploaded by the user (shown in the web).
    public required string FileName { get; set; }

    // Name on disk inside the project folder. Generated by the API, so user
    // names never become paths.
    public required string StoredName { get; set; }

    public required string ContentType { get; set; }

    public long SizeBytes { get; set; }

    // SHA-256 of the content, as 64 lowercase hex characters.
    public required string Sha256 { get; set; }

    public DateTimeOffset UploadedAt { get; set; }
}
